        "{n} cent": function(v){ var s = String(v.n), n = parseFloat(s.replace(',', '.')); if (/[.,]/.test(s)) return s + ' centa'; if (n === 1) return s + ' cent'; var j = n % 10, d = n % 100; return s + ((j >= 2 && j <= 4 && (d < 12 || d > 14)) ? ' centy' : ' centów'); },
