        "{h} halvtoner": function(v){ var n = +v.h; return n + (n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) ? ' półtony' : ' półtonów'); },
        "{a}–{b}: {navn}, {halvtoner}": "{a}–{b}: {navn}, {halvtoner}",
        "►︎ <span>spill</span>": "►︎ <span>odtwórz</span>",
        "Quiz": "Quiz",
        "Teoriquiz: intervaller": "Quiz teoretyczny: interwały",
        "Intervall<em>quiz</em>": "<em>Quiz</em> interwałów",
        "Les intervaller på notelinjen og skriv dem selv, i G- og F-nøkkel, med rene, store, små, forstørrede og forminskede intervaller. Øvemodus og prøvemodus med 20 oppgaver.": "Czytaj interwały z pięciolinii i zapisuj je sam, w kluczu wiolinowym i basowym, z interwałami czystymi, wielkimi, małymi, zwiększonymi i zmniejszonymi. Tryb ćwiczeń i test z 20 zadaniami.",
        "Les intervaller på notelinjen, og skriv dem selv ved å velge riktig notebilde, slik som på opptaksprøver. Øv i ditt eget tempo, eller ta en prøve med 20 oppgaver.": "Czytaj interwały z pięciolinii i zapisuj je, wybierając właściwy zapis nutowy, jak na egzaminach wstępnych. Ćwicz we własnym tempie albo zrób test z 20 zadaniami.",
        "Alt er forklart i leksjonen <a href=\"intervaller-teori.html\">Intervaller</a>. Etter svaret kan du høre intervallet. Velg piano, strykere eller sinustoner nederst til høyre.": "Wszystko jest wyjaśnione w lekcji <a href=\"intervaller-teori.html\">Interwały</a>. Po odpowiedzi możesz usłyszeć interwał. Wybierz fortepian, smyczki lub tony sinusoidalne w prawym dolnym rogu.",
        "Øvemodus": "Tryb ćwiczeń",
        "Prøvemodus": "Tryb testu",
        "Din fremgang": "Twoje postępy",
        "Målet er fem riktige svar på rad. Resultatet nullstilles når du laster siden på nytt.": "Celem jest pięć poprawnych odpowiedzi z rzędu. Wynik zeruje się po ponownym załadowaniu strony.",
        "Modus": "Tryb",
        "Hva vil du gjøre?": "Co chcesz robić?",
        "Velg modus": "Wybierz tryb",
        "Du får svaret med en gang, med intervallet på notelinjen, og kan høre det.": "Odpowiedź dostajesz od razu, z interwałem na pięciolinii, i możesz go usłyszeć.",
        "20 oppgaver med valgene under, og du får resultatet til slutt.": "20 zadań z poniższymi ustawieniami, a wynik dostajesz na końcu.",
        "Oppgaver": "Zadania",
        "Les intervallet": "Przeczytaj interwał",
        "Skriv intervallet": "Zapisz interwał",
        "Begge": "Oba",
        "Nivå": "Poziom",
        "Grunnleggende": "Podstawowy",
        "Avansert": "Zaawansowany",
        "Grunnleggende: rene, store og små intervaller oppover i G-nøkkel, fra toner uten fortegn. Avansert: også forstørrede og forminskede intervaller, fortegn på begge tonene, intervaller nedover, og både G- og F-nøkkel.": "Podstawowy: interwały czyste, wielkie i małe w górę w kluczu wiolinowym, od dźwięków bez znaków. Zaawansowany: także interwały zwiększone i zmniejszone, znaki przy obu dźwiękach, interwały w dół oraz klucz wiolinowy i basowy.",
        "Spill intervallet": "Odtwórz interwał",
        "Neste oppgave": "Następne zadanie",
        "Svaralternativer": "Odpowiedzi do wyboru",
        "Oppgavetypene": "Rodzaje zadań",
        "<strong>Les intervallet:</strong> to toner står på notelinjen, etter hverandre eller samtidig. Finn navnet: tall og kvalitet.": "<strong>Przeczytaj interwał:</strong> na pięciolinii stoją dwa dźwięki, jeden po drugim albo razem. Znajdź nazwę: liczbę i rodzaj.",
        "<strong>Skriv intervallet:</strong> en tone og et intervall er gitt. Velg notebildet der den andre tonen er riktig skrevet.": "<strong>Zapisz interwał:</strong> podany jest dźwięk i interwał. Wybierz zapis, w którym drugi dźwięk jest zapisany poprawnie.",
        "Tell bokstavene først, så halvtonene. Står den andre tonen i dur-skalaen fra den nederste tonen, er intervallet stort eller rent.": "Najpierw policz litery, potem półtony. Jeśli drugi dźwięk należy do gamy durowej od dolnego dźwięku, interwał jest wielki albo czysty.",
        "Prøve med 20 oppgaver": "Test z 20 zadaniami",
        "Du kan endre svaret til du går videre. Etter prøven kan du høre hvert intervall i gjennomgangen.": "Możesz zmieniać odpowiedź, dopóki nie przejdziesz dalej. Po teście możesz usłyszeć każdy interwał w przeglądzie.",
        "Start prøven": "Rozpocznij test",
        "Gjennomgang. Trykk på spill for å høre intervallet.": "Przegląd. Dotknij „odtwórz”, aby usłyszeć interwał.",
        "Ta en ny prøve": "Zrób nowy test",
        "Hvilket intervall er dette?": "Jaki to interwał?",
        "F-nøkkel": "Klucz basowy",
        "G-nøkkel": "Klucz wiolinowy",
        "Gitt tone: {tone}": "Podany dźwięk: {tone}",
        "Skriv en {navn} opp fra {tone}.": function(v){ return 'Zapisz ' + v.navn.split(' ').map(function(w, i){ return w.replace(/a$/, i ? 'ą' : 'ę'); }).join(' ') + ' w górę od ' + v.tone + '.'; },
        "Skriv en {navn} ned fra {tone}.": function(v){ return 'Zapisz ' + v.navn.split(' ').map(function(w, i){ return w.replace(/a$/, i ? 'ą' : 'ę'); }).join(' ') + ' w dół od ' + v.tone + '.'; },
        "Alternativ {n}": "Odpowiedź {n}",
        "Alternativ {n}: {tone}": "Odpowiedź {n}: {tone}",
        "{a} til {b} er en {navn}: {t} bokstaver og {halvtoner}.": function(v){ var t = +v.t, l = t === 1 ? 'litera' : (t >= 2 && t <= 4 ? 'litery' : 'liter'); return v.a + ' do ' + v.b + ' to ' + v.navn + ': ' + t + ' ' + l + ' i ' + v.halvtoner + '.'; },
        "Riktig.": "Dobrze.",
        "Feil.": "Źle.",
        "Fem riktige på rad. Målet er nådd!": "Pięć poprawnych z rzędu. Cel osiągnięty!",
        "Tre riktige på rad. Bra jobbet!": "Trzy poprawne z rzędu. Dobra robota!",
        "Ti riktige på rad. Imponerende!": "Dziesięć poprawnych z rzędu. Imponujące!",
        "Ikke gi opp. Du blir bedre for hver oppgave.": "Nie poddawaj się. Z każdym zadaniem idzie ci lepiej.",
        "Tell bokstavene først, og ta med begge tonene.": "Najpierw policz litery, wliczając oba dźwięki.",
        "Tenk på dur-skalaen fra den nederste tonen.": "Pomyśl o gamie durowej od dolnego dźwięku.",
        "Pust rolig, tenk deg om, og prøv neste.": "Oddychaj spokojnie, zastanów się i spróbuj następnego.",
        "{r} av {t} riktige.": "Poprawnie: {r} z {t}.",
        "{r} av {t} riktige": "{r} z {t} poprawnie",
